import json,re
def obj(text):
    if isinstance(text,dict): text=json.dumps(text,ensure_ascii=False)
    if not isinstance(text,str) or len(text)>16000: raise ValueError('Invalid model output size')
    text=text.strip()
    if text.startswith(chr(96)*3):
        text=re.sub(r'^```(?:json)?\s*','',text,flags=re.I)
        text=re.sub(r'\s*```$','',text)
    value=json.loads(text)
    if not isinstance(value,dict): raise ValueError('Expected a content object')
    return value
def string(value,limit):
    if not isinstance(value,str) or not value.strip() or len(value)>limit: raise ValueError('Invalid content text')
    return value.strip()
def exact(value,keys):
    if not isinstance(value,dict) or set(value)!=set(keys): raise ValueError('Unexpected content fields')
def array(value,count):
    if not isinstance(value,list) or len(value)!=count: raise ValueError('Invalid content count')
    return value
def narrative(value):
    exact(value,['title','premise','outline','characters','location','pages'])
    p={'title':string(value['title'],80),'premise':string(value['premise'],250),'outline':[string(x,200) for x in array(value['outline'],3)]}
    p['characters']=[]
    for c in array(value['characters'],2):
        exact(c,['name','appearance','role'])
        p['characters'].append({'name':string(c['name'],40),'appearance':string(c['appearance'],220),'role':string(c['role'],100)})
    if len(set(c['name'].casefold() for c in p['characters']))!=2: raise ValueError('Duplicate character names')
    exact(value['location'],['name','description'])
    p['location']={'name':string(value['location']['name'],60),'description':string(value['location']['description'],200)}
    p['pages']=[]
    for page in array(value['pages'],3):
        exact(page,['narration','scene'])
        p['pages'].append({'narration':string(page['narration'],280),'scene':string(page['scene'],250)})
    return p
def visual(value):
    exact(value,['decision','style','characterSheets','locationSheet','cover','pages'])
    if value['decision'] not in ['proceed','stop']: raise ValueError('Invalid review decision')
    p={'decision':value['decision'],'style':string(value['style'],350),'characterSheets':[string(x,180) for x in array(value['characterSheets'],2)],'locationSheet':string(value['locationSheet'],180),'cover':string(value['cover'],250),'pages':[]}
    for page in array(value['pages'],3):
        exact(page,['scene','lettering'])
        p['pages'].append({'scene':string(page['scene'],280),'lettering':string(page['lettering'],180)})
    return p
def pack(value):
    text=json.dumps(value,ensure_ascii=False,separators=(',',':'))
    if len(text)>8000: raise ValueError('Comic package exceeds artifact bounds')
    return text
def main(text: str) -> dict:
    p=narrative(obj(text))
    return {'package':pack(p),'text':p['title']+'\n'+p['premise']+'\n'+'\n'.join(x['narration'] for x in p['pages'])}

