import json
def main(text: str, files1: list, files2: list, files3: list, files4: list, files5: list, files6: list, files7: list, files8: list, files9: list) -> dict:
    groups=[files1, files2, files3, files4, files5, files6, files7, files8, files9]
    files=[]
    for group in groups:
        if not isinstance(group,list) or len(group)!=1 or not isinstance(group[0],dict) or group[0].get('type')!='image': raise ValueError('Expected one generated image per task')
        files.extend(group)
    p=json.loads(text)
    result=p['title']+'\n\n'+'\n\n'.join('Page '+str(i+1)+': '+x['narration'] for i,x in enumerate(p['stages']['J05']['pages']))+'\n\nImage order: '+', '.join(p['stages']['J13']['assetOrder'])
    return {'result':json.dumps({'version':1,'outcome':'success','text':result,'cards':[],'images':[]},ensure_ascii=False),'images':files}

